/* CBT Toolkit service worker — offline support.
   - App files are precached at install (list generated by `npm run build`).
   - Navigations: network first, falling back to the cached app shell when offline.
   - Static assets: served from cache, refreshed in the background (stale-while-revalidate).
   - Cross-origin requests (e.g. Google AdSense) are never cached or touched. */

// BUILD-START (generated by scripts/build.mjs — do not edit by hand)
const VERSION = 'febe9270a8c9';
const PRECACHE = ["./", "css/app.css", "favicon.svg", "icons/icon-192.png", "icons/icon-512.png", "icons/maskable-512.png", "index.html", "js/app.js", "js/config.js", "js/core/dom.js", "js/core/format.js", "js/core/icons.js", "js/core/perf.js", "js/core/router.js", "js/core/store.js", "js/data/areas.js", "js/data/assessments.js", "js/data/courses.js", "js/data/daily.js", "js/data/exercises/_fields.js", "js/data/exercises/anxiety.js", "js/data/exercises/depression.js", "js/data/exercises/impulsiveness.js", "js/data/exercises/index.js", "js/data/exercises/productivity.js", "js/data/exercises/self-discipline.js", "js/data/exercises/sexual-desire.js", "js/data/exercises/time-management.js", "js/data/learn.js", "js/data/programs.js", "js/data/research.js", "js/data/resources.js", "js/lib/ads.js", "js/lib/charts.js", "js/lib/coach.js", "js/lib/crypto.js", "js/lib/ics.js", "js/lib/install.js", "js/lib/report.js", "js/lib/sanitize.js", "js/lib/search-index.js", "js/lib/search.js", "js/lib/stats.js", "js/lib/stemmer.js", "js/lib/therapy.js", "js/theme-init.js", "js/ui/components.js", "js/ui/cycle.js", "js/ui/forms.js", "js/ui/records.js", "js/ui/save.js", "js/ui/widgets/calculators.js", "js/ui/widgets/index.js", "js/ui/widgets/quiz.js", "js/ui/widgets/timers.js", "js/ui/widgets/tools.js", "js/views/area.js", "js/views/checkin.js", "js/views/course.js", "js/views/exercise.js", "js/views/help.js", "js/views/home.js", "js/views/journal.js", "js/views/learn.js", "js/views/mood.js", "js/views/pages.js", "js/views/plan.js", "js/views/programs.js", "js/views/reports.js", "js/views/research.js", "js/views/search.js", "js/views/settings.js", "js/views/standards.js", "js/views/today.js", "js/views/toolbox.js", "manifest.webmanifest"];
// BUILD-END

const CACHE = `cbt-toolkit-${VERSION}`;

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE)
      .then((cache) => cache.addAll(PRECACHE.map((p) => new Request(p, { cache: 'reload' }))))
      .catch(() => { /* a missing file must not block installation */ })
  );
  self.skipWaiting();
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    const keys = await caches.keys();
    await Promise.all(keys.filter((k) => k.startsWith('cbt-toolkit-') && k !== CACHE).map((k) => caches.delete(k)));
    await self.clients.claim();
  })());
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;

  if (req.mode === 'navigate') {
    event.respondWith((async () => {
      try {
        const fresh = await fetch(req);
        const cache = await caches.open(CACHE);
        cache.put('index.html', fresh.clone());
        return fresh;
      } catch {
        return (await caches.match('index.html')) || (await caches.match('./')) || Response.error();
      }
    })());
    return;
  }

  event.respondWith((async () => {
    const cache = await caches.open(CACHE);
    const cached = await cache.match(req, { ignoreSearch: true });
    const network = fetch(req).then((res) => {
      if (res && res.ok && res.type === 'basic') cache.put(req, res.clone());
      return res;
    }).catch(() => null);
    return cached || (await network) || Response.error();
  })());
});
